<?php
namespace App\Http\Controllers;
use App\Models\{Cart,Product,Order}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CartController extends Controller { private function cart(Request $r):Cart{return $r->user()->cart()->firstOrCreate([]);} public function show(Request $r){return $this->cart($r)->load('items.product');} public function add(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1|max:100']);$p=Product::findOrFail($d['product_id']);abort_unless($p->is_active&&$p->stock_quantity>=$d['quantity'],422,'Product is unavailable or stock is insufficient.');$c=$this->cart($r);$i=$c->items()->firstOrNew(['product_id'=>$p->id]);$i->quantity=min(100,$i->quantity+$d['quantity']);$i->save();return $c->load('items.product');} public function update(Request $r,$item){$d=$r->validate(['quantity'=>'required|integer|min:1|max:100']);$c=$this->cart($r);$i=$c->items()->with('product')->findOrFail($item);abort_unless($i->product->is_active&&$i->product->stock_quantity>=$d['quantity'],422);$i->update($d);return $c->load('items.product');} public function remove(Request $r,$item){$c=$this->cart($r);$c->items()->whereKey($item)->delete();return $c->load('items.product');} public function checkout(Request $r){$c=$this->cart($r)->load('items.product');abort_if($c->items->isEmpty(),422,'Cart is empty.');$order=DB::transaction(function()use($c,$r){$subtotal=0;foreach($c->items as $i){$p=Product::lockForUpdate()->findOrFail($i->product_id);abort_unless($p->is_active&&$p->stock_quantity>=$i->quantity,422,'Stock changed for '.$p->name);$subtotal+=(float)$p->price*$i->quantity;} $o=$r->user()->orders()->create(['status'=>'requested','subtotal'=>$subtotal,'notes'=>$r->string('notes')->toString()]);foreach($c->items as $i){$p=Product::lockForUpdate()->findOrFail($i->product_id);$line=(float)$p->price*$i->quantity;$o->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'unit_price'=>$p->price,'quantity'=>$i->quantity,'line_total'=>$line]);$p->decrement('stock_quantity',$i->quantity);} $c->items()->delete();return $o->load('items');});return response()->json(['message'=>'Order recorded. FurShield does not process online payments.','order'=>$order],201);} public function orders(Request $r){return $r->user()->orders()->with('items')->latest()->paginate(20);} public function order(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id||$r->user()->role==='admin',403);return $order->load('items');} }
